// Tratamento e Estruturação Completa do Lead
const input = $input.first().json.body || $input.first().json;

const email = (input.email || '').trim().toLowerCase();
const dataAtual = new Date();

// Formatação data BR
const dataFormatada = new Intl.DateTimeFormat('pt-BR', {
  dateStyle: 'short',
  timeStyle: 'medium',
  timeZone: 'America/Sao_Paulo'
}).format(dataAtual);

// Extrai primeiro nome sugerido (ex: maria.silva@ -> Maria)
const rawName = email.split('@')[0].split('.')[0].replace(/[0-9_]/g, '');
const nomeSugerido = rawName ? (rawName.charAt(0).toUpperCase() + rawName.slice(1)) : 'Inscrito';

return [{
  json: {
    id: 'LEAD-' + Date.now(),
    email: email,
    nomeSugerido: nomeSugerido,
    origem: input.origem || 'Landing Page Em Desenvolvimento',
    marca: input.marca || 'Gabriela Lopes',
    dataRegistroBR: dataFormatada,
    timestampISO: dataAtual.toISOString(),
    status: 'Novo Lead'
  }
}];
